# Break My Fix finding 2, generated by Tracefix: parse_tax_lvl raises NameError.
# Property (docstring): The returned dict maps the entry's own named rank to its scientific name without the indentation, whatever was recorded before.
# Quote: Parse a single kraken-report entry and return a dictionary of taxa for its named ranks.
# Run it with pytest: it fails for as long as the code breaks this property.

from kraken_biom import parse_tax_lvl, ranks


def test_break_my_fix_2() -> None:
    entry = {'pct_reads': '0.00', 'clade_reads': '1', 'taxon_reads': '0', 'rank': 'P', 'ncbi_tax': '3041', 'sci_name': 'Chlorophyta'}
    # The property applies to this input: entry['rank'] in ranks and '\n' not in entry['sci_name'] and entry['sci_name'] == entry['sci_name'].rstrip(' ') and entry['sci_name'].strip(' ') != ''
    result = parse_tax_lvl(entry={'pct_reads': '0.00', 'clade_reads': '1', 'taxon_reads': '0', 'rank': 'P', 'ncbi_tax': '3041', 'sci_name': 'Chlorophyta'})
    assert (isinstance(result, dict) and result.get(entry['rank']) == entry['sci_name'].strip(' '))
